sqlExercise.schemaSql:
CREATE TABLE employees (
    -- id integer primary key autoincrement,
    role text,
    name text,
    building text,
    years_employed integer
);
CREATE TABLE buildings (
    building_name text,
    capacity int
);

CREATE TABLE movies (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT,
    director TEXT,
    year INTEGER,
    length_minutes INTEGER
);
CREATE TABLE boxoffice (
    movie_id INTEGER,
    rating REAL,
    domestic_sales REAL,
    international_sales REAL
);

